-- Postgres schema for chess-ui (migrated from the SQL Server DB.mdf).
-- Runs once, on first start of the postgres container (docker-entrypoint-initdb.d).
CREATE TABLE users (
    Id              SERIAL PRIMARY KEY,
    username        VARCHAR(520) NOT NULL,
    password        VARCHAR(520) NOT NULL,
    nickname        VARCHAR(10)  NOT NULL DEFAULT 'anonymous',
    mail            CHAR(20)     NOT NULL,
    age             INTEGER,
    country         CHAR(10),
    city            CHAR(10),
    change_password DATE         NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE Games (
    game_id    SERIAL PRIMARY KEY,
    date_time  TIMESTAMP NOT NULL DEFAULT now(),
    wplayerid  INTEGER,
    bplayerid  INTEGER,
    moves      TEXT      NOT NULL
);

-- Seed data copied from DB.mdf
SELECT setval(pg_get_serial_sequence('users','id'), (SELECT MAX(Id) FROM users));
SELECT setval(pg_get_serial_sequence('games','game_id'), (SELECT MAX(game_id) FROM games));
